const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const bryce = ee.Geometry.Polygon([
      [[-112.38, 37.38], [-112.38, 37.82], [-112.05, 37.82], [-112.05, 37.38], [-112.38, 37.38]]
    ]);
    const vegas = ee.Geometry.Polygon([
      [[-115.38, 35.98], [-115.38, 36.40], [-114.85, 36.40], [-114.85, 35.98], [-115.38, 35.98]]
    ]);
    const start = '2024-01-01';
    const end = '2025-01-01';

    // 2. Data Acquisition & Check
    let datasetId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
    let col = ee.ImageCollection(datasetId).filterDate(start, end).select('avg_rad');
    let size = await col.size().getInfo();
    if (size === 0) {
      datasetId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG';
      col = ee.ImageCollection(datasetId).filterDate(start, end).select('avg_rad');
      size = await col.size().getInfo();
    }
    if (size === 0) {
      console.log('2024 images: 0');
      console.log('C1');
      return;
    }
    console.log(`Dataset: ${datasetId}, 2024 images: ${size}`);

    // 3. Processing (Median 2024)
    const img = col.median().select('avg_rad');

    // 4. Counts and Means
    const reducer = ee.Reducer.mean().combine(ee.Reducer.count(), true);
    const bryceStats = await img.reduceRegion({
      reducer: reducer, geometry: bryce, scale: 1000, maxPixels: 1e9
    }).getInfo();
    const vegasStats = await img.reduceRegion({
      reducer: reducer, geometry: vegas, scale: 1000, maxPixels: 1e9
    }).getInfo();

    const bCount = bryceStats['avg_rad_count'];
    const vCount = vegasStats['avg_rad_count'];
    const bMean = bryceStats['avg_rad_mean'];
    const vMean = vegasStats['avg_rad_mean'];

    if ((bCount === 0 || vCount === 0) || (bCount == null || vCount == null)) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }
    if ([bMean, vMean].some(x => x === null || x === undefined || Number.isNaN(x) || !isFinite(x))) {
      console.log('Calculation failed (mean is null/NaN).');
      console.log('C3');
      return;
    }

    console.log(`Bryce px: ${bCount}, mean nW/cm^2/sr: ${bMean.toFixed(3)}`);
    console.log(`LasVegas px: ${vCount}, mean nW/cm^2/sr: ${vMean.toFixed(3)}`);
    const ratio = bMean / (vMean === 0 ? 1e-9 : vMean);
    console.log(`Bryce/LasVegas ratio: ${ratio.toFixed(3)}`);

    // 5. Final Answer
    const result = bMean < vMean ? 'A' : 'B';
    console.log(result);
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
